import { test, expect } from '@playwright/test';

test.describe('API Response Caching', () => {
  const API_BASE_URL = 'https://jsonplaceholder.typicode.com';
  const TEST_ENDPOINT = '/posts/1';

  test.beforeEach(async ({ page }) => {
    // Clear any existing cache before each test
    await page.context().clearCookies();
    await page.evaluate(() => {
      if ('caches' in window) {
        caches.keys().then(names => {
          names.forEach(name => caches.delete(name));
        });
      }
    });
  });

  test('should cache API response on first request', async ({ page }) => {
    let requestCount = 0;

    // Monitor network requests
    page.on('response', (response) => {
      if (response.url().includes(API_BASE_URL)) {
        requestCount++;
      }
    });

    // Navigate to page that makes API call
    await page.goto('data:text/html,<html><body><div id="content"></div><script>
      const cache = {};
      async function fetchWithCache(url) {
        if (cache[url]) {
          console.log("Cache hit for " + url);
          document.getElementById("content").textContent = JSON.stringify(cache[url]);
          return cache[url];
        }
        const response = await fetch(url);
        const data = await response.json();
        cache[url] = data;
        console.log("Cache miss for " + url);
        document.getElementById("content").textContent = JSON.stringify(data);
        return data;
      }
      window.fetchWithCache = fetchWithCache;
    </script></body></html>');

    // First request should hit the API
    await page.evaluate((url) => window.fetchWithCache(url), `${API_BASE_URL}${TEST_ENDPOINT}`);

    const firstRequestCount = requestCount;
    expect(firstRequestCount).toBeGreaterThan(0);

    // Verify content is displayed
    const content = await page.locator('#content').textContent();
    expect(content).toContain('sunt aut facere repellat provident');
  });

  test('should return cached response on repeat visit without additional API call', async ({ page }) => {
    let networkRequests: string[] = [];

    // Monitor all network requests
    page.on('response', (response) => {
      if (response.url().includes(API_BASE_URL)) {
        networkRequests.push(response.url());
      }
    });

    // Set up page with caching mechanism
    await page.goto('data:text/html,<html><body><div id="content"></div><div id="cache-status"></div><script>
      const cache = {};
      async function fetchWithCache(url) {
        if (cache[url]) {
          document.getElementById("cache-status").textContent = "CACHED";
          document.getElementById("content").textContent = JSON.stringify(cache[url]);
          return cache[url];
        }
        document.getElementById("cache-status").textContent = "FETCHING";
        const response = await fetch(url);
        const data = await response.json();
        cache[url] = data;
        document.getElementById("content").textContent = JSON.stringify(data);
        return data;
      }
      window.fetchWithCache = fetchWithCache;
    </script></body></html>');

    // First request
    await page.evaluate((url) => window.fetchWithCache(url), `${API_BASE_URL}${TEST_ENDPOINT}`);
    const firstRequestsCount = networkRequests.length;

    // Wait for first request to complete
    await page.waitForTimeout(500);

    // Verify first request was made
    expect(firstRequestsCount).toBeGreaterThan(0);

    // Second request should use cache
    networkRequests = [];
    await page.evaluate((url) => window.fetchWithCache(url), `${API_BASE_URL}${TEST_ENDPOINT}`);

    // Verify cache status
    const cacheStatus = await page.locator('#cache-status').textContent();
    expect(cacheStatus).toBe('CACHED');

    // Verify no additional API call was made
    expect(networkRequests.length).toBe(0);

    // Verify content is still correct
    const content = await page.locator('#content').textContent();
    expect(content).toContain('sunt aut facere repellat provident');
  });

  test('should maintain cache across multiple rapid requests', async ({ page }) => {
    let apiCallCount = 0;

    page.on('response', (response) => {
      if (response.url().includes(API_BASE_URL)) {
        apiCallCount++;
      }
    });

    await page.goto('data:text/html,<html><body><div id="results"></div><script>
      const cache = {};
      const callLog = [];
      async function fetchWithCache(url) {
        if (cache[url]) {
          callLog.push("HIT");
          return cache[url];
        }
        callLog.push("MISS");
        const response = await fetch(url);
        const data = await response.json();
        cache[url] = data;
        return data;
      }
      window.fetchWithCache = fetchWithCache;
      window.getCallLog = () => callLog;
    </script></body></html>');

    // Make multiple rapid requests
    for (let i = 0; i < 5; i++) {
      await page.evaluate((url) => window.fetchWithCache(url), `${API_BASE_URL}${TEST_ENDPOINT}`);
    }

    // Check call log
    const callLog = await page.evaluate(() => window.getCallLog());

    // First call should be a miss, rest should be hits
    expect(callLog[0]).toBe('MISS');
    expect(callLog[1]).toBe('HIT');
    expect(callLog[2]).toBe('HIT');
    expect(callLog[3]).toBe('HIT');
    expect(callLog[4]).toBe('HIT');

    // Only one actual API call should have been made
    expect(apiCallCount).toBe(1);
  });

  test('should handle cache invalidation correctly', async ({ page }) => {
    let apiCallCount = 0;

    page.on('response', (response) => {
      if (response.url().includes(API_BASE_URL)) {
        apiCallCount++;
      }
    });

    await page.goto('data:text/html,<html><body><div id="status"></div><script>
      const cache = {};
      async function fetchWithCache(url) {
        if (cache[url]) {
          return cache[url];
        }
        const response = await fetch(url);
        const data = await response.json();
        cache[url] = data;
        return data;
      }
      function invalidateCache(url) {
        delete cache[url];
      }
      window.fetchWithCache = fetchWithCache;
      window.invalidateCache = invalidateCache;
    </script></body></html>');

    const url = `${API_BASE_URL}${TEST_ENDPOINT}`;

    // First request
    await page.evaluate((u) => window.fetchWithCache(u), url);
    const firstCallCount = apiCallCount;
    expect(firstCallCount).toBe(1);

    // Second request (cached)
    await page.evaluate((u) => window.fetchWithCache(u), url);
    expect(apiCallCount).toBe(1);

    // Invalidate cache
    await page.evaluate((u) => window.invalidateCache(u), url);

    // Third request (should hit API again)
    await page.evaluate((u) => window.fetchWithCache(u), url);
    expect(apiCallCount).toBe(2);
  });
});
